create or replace function public.finish_forecast_scheduled_job(p_run_id uuid,p_worker_id text,p_success boolean,p_records integer,p_metrics jsonb,p_error text,p_now timestamptz default now())returns void language plpgsql security definer set search_path=public as $$declare j scheduled_jobs;r scheduled_job_runs;failures int;begin select*into r from scheduled_job_runs where id=p_run_id and worker_id=p_worker_id for update;if not found then raise exception'Run lease not owned';end if;select*into j from scheduled_jobs where id=r.job_id for update;failures=case when p_success then 0 else j.consecutive_failures+1 end;update scheduled_job_runs set status=case when p_success then'SUCCEEDED'else'FAILED'end,finished_at=p_now,heartbeat_at=p_now,records_processed=p_records,metrics=coalesce(p_metrics,'{}'),error=p_error where id=r.id;update scheduled_jobs set status=case when p_success then'HEALTHY'when failures>=3 then'FAILED'else'DEGRADED'end,next_run_at=case when p_success then greatest(r.scheduled_for+(interval_seconds||' seconds')::interval,p_now+(interval_seconds||' seconds')::interval) else p_now+(least(3600,30*power(2,greatest(0,failures-1)))||' seconds')::interval end,last_successful_run_at=case when p_success then p_now else last_successful_run_at end,last_heartbeat_at=p_now,locked_at=null,locked_by=null,consecutive_failures=failures,last_error=p_error,metrics=coalesce(p_metrics,'{}'),updated_at=p_now where id=j.id;end$$;
